+    private boolean retainReferencedMembers(TextBuffer buffer) {
+      boolean changed = false;
+      for (TextToken token : buffer.getTokens()) {
+        if (token.isDeclaration()) {
+          continue;
+        }
+
+        RetentionMember member = null;
+        if (token instanceof FieldTextToken field) {
+          member = new RetentionMember(RetentionMemberType.FIELD, field.className, field.name, field.descriptor.descriptorString);
+        }
+        else if (token instanceof MethodTextToken method) {
+          member = new RetentionMember(RetentionMemberType.METHOD, method.className, method.name, method.descriptor.toString());
+        }
+        else if (token instanceof ClassTextToken clazz) {
+          member = new RetentionMember(RetentionMemberType.CLASS, clazz.qualifiedName, null, null);
+        }
+
+        if (member != null && candidates.contains(member)) {
+          changed |= retained.add(member);
+        }
+      }
+      return changed;
+    }
